//! Adversarial admission/receipt chronology through the public run_json boundary.
//! Positive states are generated by ordinary commands; hashes are rewritten only
//! in explicit negative fixtures to show that public checksums are not authority.
use mstrchf_browser::{BoardOptions, run_json};
use mstrchf_contracts::*;
use serde_json::{Value, json};

use mstrchf_browser::personal_scope;
use personal_scope::PORRIDGE_PERSONAL_SCOPE;

const NOW: &str = "2026-10-12T20:00:00Z";
const LATER: &str = "2026-10-26T20:00:00Z";
fn call(request: Value) -> Value {
    serde_json::from_slice(&run_json(&serde_json::to_vec(&request).unwrap())).unwrap()
}
fn good(request: Value) -> Value {
    let out = call(request);
    assert_eq!(out["ok"], true, "{out}");
    out["value"].clone()
}
fn legacy() -> Value {
    serde_json::from_slice::<Value>(include_bytes!("fixtures/legacy-engineering-receipts.json"))
        .unwrap()["state"].clone()
}
fn packet() -> Value {
    json!({"recipe":{"recipe_id":PORRIDGE_PERSONAL_SCOPE.recipe_id,
        "revision":PORRIDGE_PERSONAL_SCOPE.recipe_revision.to_string(),
        "digest":PORRIDGE_PERSONAL_SCOPE.recipe_digest},
        "packet_digest":PORRIDGE_PERSONAL_SCOPE.packet_canonical_digest})
}
fn command(state: &Value, body: Value, id: u32) -> Value {
    json!({"schema_version":1,"command_id":format!("cm_{id:032x}"),
        "expected_snapshot_revision":state["snapshot"]["snapshot_revision"],"command":body})
}
fn apply(state: &Value, body: Value, id: u32, now: &str) -> Value {
    let envelope = command(state, body, id);
    good(json!({"op":"dispatch","state":state,"command":envelope,
        "command_json":serde_json::to_string(&envelope).unwrap(),"now":now}))
}
fn admit_body(revision: &str) -> Value {
    json!({"kind":"admit_reviewed_recipe","data":{"packet":packet(),
        "expected_catalogue_revision":revision}})
}
fn edit(state: &Value, week: &Value, id: u32, now: &str) -> Value {
    apply(state,json!({"kind":"save_week","data":{"expected_week_revision":week["revision"],
        "week":{"week_id":week["range"]["week_id"],"defaults_snapshot":week["defaults_snapshot"],
        "day_enabled":week["day_enabled"],"meal_type_enabled":week["meal_type_enabled"],
        "cells":week["cells"],"plan":week["plan"]}}}),id,now)["state"].clone()
}
fn unrestricted(state: &Value, id: u32) -> Value {
    let mut profile=state["snapshot"]["profile"].clone();
    assert_eq!(profile["diners"].as_array().unwrap().len(),1);
    profile["diners"][0]["age_band"]=json!("adult");
    profile["diners"][0]["restrictions"]=json!({"kind":"confirmed_none","data":{"confirmed_at":NOW}});
    profile["diners"][0]["portions"]=json!({"preset":"regular","adjustment":{"numerator":"1","denominator":"1"},"meal_overrides":[]});
    apply(state,json!({"kind":"update_profile","data":{"expected_profile_revision":profile["revision"],"profile":profile}}),id,NOW)["state"].clone()
}
fn breakfast_context() -> (Value, Value) {
    let mut state=unrestricted(&legacy(),100);
    let mut week=state["snapshot"]["weeks"][0].clone();
    let index=week["cells"].as_array().unwrap().iter().position(|cell|
        cell["slot"]["meal_type"]=="breakfast"&&cell["slot"]["date"]!=week["range"]["monday"]
    ).unwrap();
    let slot=week["cells"][index]["slot"].clone();
    week["day_enabled"]=json!([true,true,true,true,true,true,true]);
    week["meal_type_enabled"]["breakfast"]=json!(true);
    week["cells"][index]["choice"]=json!("at_home");
    week["cells"][index]["attendee_ids"]=json!([state["snapshot"]["profile"]["diners"][0]["diner_id"]]);
    week["cells"][index]["occasion"]=Value::Null;
    state=edit(&state,&week,101,NOW);
    (state,slot)
}
fn board(state: &Value,slot: &Value,now: &str) -> Value {
    good(json!({"op":"board","state":state,"week_id":slot["week_id"],"slot":slot,"now":now}))
}
fn porridge_choice(board: &Value) -> Option<&Value> {
    board["choices"].as_array().unwrap().iter().find(|choice|
        choice["selection"]["recipe"]==packet()["recipe"])
}
fn selected_context() -> (Value,Value,usize) {
    let (before,slot)=breakfast_context();
    assert!(porridge_choice(&board(&before,&slot,NOW)).is_none());
    let admission_index=before["receipts"].as_array().unwrap().len();
    let admitted=apply(&before,admit_body("1"),102,NOW)["state"].clone();
    let offers=board(&admitted,&slot,NOW);
    let choice=porridge_choice(&offers).expect("admitted R3 source serving is available in its narrow scope");
    let mut week=admitted["snapshot"]["weeks"][0].clone();
    week["plan"]=choice["plan"].clone();
    let saved=edit(&admitted,&week,103,NOW);
    (saved,slot,admission_index)
}
fn validate_cold(state: Value,now: &str) -> Value {
    let now=now.to_owned();
    std::thread::spawn(move||good(json!({"op":"validate_state","state":state,"now":now})))
        .join().unwrap()
}
fn negative_warm_and_cold(state: Value) {
    assert_eq!(call(json!({"op":"validate_state","state":state,"now":NOW}))["ok"],false);
    let cold=std::thread::spawn(move||call(json!({"op":"validate_state","state":state,"now":NOW}))).join().unwrap();
    assert_eq!(cold["ok"],false);
}
fn rehash_receipt(receipt: &mut Value) {
    let envelope:AppCommandV1=parse_document(&serde_json::to_vec(&receipt["command"]).unwrap()).unwrap();
    receipt["command_digest"]=json!(canonical_digest(&envelope).unwrap().0);
    let snapshot:Snapshot=parse_document(&serde_json::to_vec(&receipt["response"]).unwrap()).unwrap();
    receipt["response_digest"]=json!(canonical_digest(&snapshot).unwrap().0);
}
fn resequence(state: &mut Value) {
    let receipts=state["receipts"].as_array_mut().unwrap();
    for (index,receipt) in receipts.iter_mut().enumerate() {
        receipt["command"]["expected_snapshot_revision"]=json!((index+1).to_string());
        receipt["snapshot_revision"]=json!((index+2).to_string());
        receipt["response"]["snapshot_revision"]=json!((index+2).to_string());
        rehash_receipt(receipt);
    }
    let final_revision=(receipts.len()+1).to_string();
    state["snapshot"]["snapshot_revision"]=json!(final_revision);
}
fn saved_selection<'a>(state: &'a Value,slot: &Value) -> &'a Value {
    state["retained_weeks"].as_array().unwrap().iter().flat_map(|w|w["plan"]["selections"].as_array().unwrap())
        .find(|selection|selection["slot"]==*slot).unwrap()
}

#[test]
fn legacy_journal_admission_and_porridge_save_cold_restore_preserve_original_receipts_and_replays() {
    let original=legacy();
    let (state,_,admission_index)=selected_context();
    for index in 0..original["receipts"].as_array().unwrap().len() {
        assert_eq!(state["receipts"][index],original["receipts"][index]);
        let envelope=&state["receipts"][index]["command"];
        let replay=good(json!({"op":"dispatch","state":state,"command":envelope,"now":NOW}));
        assert_eq!(replay["state"],state);
        assert_eq!(replay["receipt"]["response_digest"],state["receipts"][index]["response_digest"]);
    }
    let receipt=&state["receipts"][admission_index];
    let mut expected=state["receipts"][admission_index-1]["response"].clone();
    expected["snapshot_revision"]=receipt["snapshot_revision"].clone();
    assert_eq!(receipt["response"],expected,"Admission changes ownership, not original food effects");
    assert_eq!(receipt["food_catalogue_pin"]["revision"],"2");
    assert_eq!(state["reviewed_packets"].as_array().unwrap().len(),1);
    assert_eq!(validate_cold(state.clone(),NOW),state);
    let accepted=serde_json::from_slice::<Value>(include_bytes!("fixtures/legacy-engineering-receipts.json")).unwrap()["accepted_result"].clone();
    let duplicate=good(json!({"op":"return_proposal","state":state,"result":accepted,"now":NOW}));
    assert_eq!(duplicate["status"],"already_applied");
    assert!(duplicate["command"].is_null());
    assert_eq!(duplicate["state"],state,"Accepted no-op returns the identical state");
}

#[test]
fn admission_replay_is_exact_and_changed_stale_or_duplicate_intents_do_not_add_authority() {
    let before=legacy();
    let envelope=command(&before,admit_body("1"),200);
    let applied=good(json!({"op":"dispatch","state":before,"command":envelope,"now":NOW}));
    let state=&applied["state"];
    let replay=good(json!({"op":"dispatch","state":state,"command":envelope,"now":NOW}));
    assert_eq!(replay["state"],*state);
    assert_eq!(replay["receipt"]["disposition"],"replayed");
    assert_eq!(replay["receipt"]["response_digest"],applied["receipt"]["response_digest"]);
    let mut changed=envelope.clone();changed["command"]["data"]["packet"]["packet_digest"]=json!("f".repeat(64));
    assert_eq!(call(json!({"op":"dispatch","state":state,"command":changed,"now":NOW}))["error"]["code"],"replay_conflict");
    for (id,revision) in [(201,"1"),(202,"2")] {
        let next=command(state,admit_body(revision),id);
        assert_eq!(call(json!({"op":"dispatch","state":state,"command":next,"now":NOW}))["ok"],false);
    }
    assert_eq!(validate_cold(state.clone(),NOW),*state);
}

#[test]
fn missing_moved_or_preclaimed_admission_cannot_rewrite_catalogue_chronology_even_with_rehashed_receipts() {
    let (state,_,index)=selected_context();
    good(json!({"op":"validate_state","state":state,"now":NOW}));
    let mut missing=state.clone();missing["receipts"].as_array_mut().unwrap().remove(index);resequence(&mut missing);
    negative_warm_and_cold(missing);
    let mut moved=state.clone();moved["receipts"].as_array_mut().unwrap().swap(index,index+1);resequence(&mut moved);
    negative_warm_and_cold(moved);
    let mut before=state.clone();before["receipts"][index-1]["food_catalogue_pin"]=state["receipts"][index]["food_catalogue_pin"].clone();
    negative_warm_and_cold(before);
    let mut omitted=state.clone();omitted["receipts"][index+1].as_object_mut().unwrap().remove("food_catalogue_pin");
    negative_warm_and_cold(omitted);
}

#[test]
fn admission_or_earlier_response_cannot_claim_new_food_or_new_plans_from_a_later_receipt() {
    let (state,_,index)=selected_context();
    let final_week=state["snapshot"]["weeks"][0].clone();
    for receipt_index in [index-1,index] {
        let mut corrupted=state.clone();
        corrupted["receipts"][receipt_index]["response"]["weeks"][0]=final_week.clone();
        rehash_receipt(&mut corrupted["receipts"][receipt_index]);
        negative_warm_and_cold(corrupted);
    }
    let mut final_forgery=state.clone();
    final_forgery["snapshot"]["weeks"][0]["plan"]["selections"].as_array_mut().unwrap().clear();
    negative_warm_and_cold(final_forgery);
    let mut retained_forgery=state.clone();
    retained_forgery["retained_weeks"][0]["plan"]["selections"].as_array_mut().unwrap().clear();
    negative_warm_and_cold(retained_forgery);
}

#[test]
fn later_valid_food_proof_cannot_authorise_an_unqualified_original_selection_response() {
    let (state,_,index)=selected_context();
    let profile=state["snapshot"]["profile"].clone();
    // A later ordinary profile receipt contains this same selection and can
    // independently derive it. It must not repair its first admission context.
    let mut corrupted=apply(&state,json!({"kind":"update_profile","data":{
        "expected_profile_revision":profile["revision"],"profile":profile}}),250,NOW)["state"].clone();
    good(json!({"op":"validate_state","state":corrupted,"now":NOW}));
    corrupted["receipts"][index+1]["response"]["profile"]["diners"][0]["age_band"]=json!("teen");
    rehash_receipt(&mut corrupted["receipts"][index+1]);
    negative_warm_and_cold(corrupted);
}

#[test]
fn demo_requires_an_ordinary_saved_receipt_and_cannot_restore_admission_as_its_first_receipt() {
    let demo=good(json!({"op":"initialize","household_id":"hh_80000000000000000000000000000001",
        "diner_id":"dn_80000000000000000000000000000001","zone":"Europe/London",
        "today":"2026-10-12","now":NOW,"demo":true}));
    let initial=command(&demo,admit_body("1"),300);
    assert_eq!(call(json!({"op":"dispatch","state":demo,"command":initial,"now":NOW}))["ok"],false);
    let saved=apply(&demo,json!({"kind":"open_planning_horizon","data":{}}),301,NOW)["state"].clone();
    let admitted=apply(&saved,admit_body("1"),302,NOW)["state"].clone();
    assert_eq!(validate_cold(admitted.clone(),NOW),admitted);
    let mut fabricated=admitted;fabricated["receipts"].as_array_mut().unwrap().remove(0);resequence(&mut fabricated);
    negative_warm_and_cold(fabricated);
}

#[test]
fn an_exact_empty_initial_response_cannot_admit_before_any_saved_kitchen() {
    let before=legacy();
    let mut forged=apply(&before,admit_body("1"),350,NOW)["state"].clone();
    let new_pin=forged["receipts"].as_array().unwrap().last().unwrap()["food_catalogue_pin"].clone();
    let initial=good(json!({"op":"initialize","household_id":before["snapshot"]["household_draft"]["household_id"],
        "diner_id":before["snapshot"]["profile"]["diners"][0]["diner_id"],"zone":"Europe/London",
        "today":"2026-10-12","now":NOW,"demo":false}));
    assert!(initial["snapshot"]["profile"].is_null());
    let receipts=forged["receipts"].as_array_mut().unwrap();
    let mut admission=receipts.pop().unwrap();
    admission["response"]=initial["snapshot"].clone();
    // Chronological equality and every public hash can be made self-consistent;
    // an ordinary saved-kitchen response still has to precede the admission.
    receipts.insert(0,admission);
    for receipt in receipts { receipt["food_catalogue_pin"]=new_pin.clone(); }
    resequence(&mut forged);
    negative_warm_and_cold(forged);
}

#[test]
fn admission_revokes_pending_request_without_rewriting_accepted_legacy_result_authority() {
    let before=legacy();
    assert_eq!(before["snapshot"]["privacy"]["use_ai_features"],true);
    let week=&before["snapshot"]["weeks"][1];
    let slot=&week["cells"][2]["slot"];
    let prepared=good(json!({"op":"prepare_proposal","state":before,"week_id":week["range"]["week_id"],
        "slots":[slot],"mode":"fill_open","allow_repeats":false,"nonce":"rq_80000000000000000000000000000001","now":NOW}));
    let request=&prepared["request"];
    let result=json!({"proposal_id":request["proposal_id"],"context_digest":request["context_digest"],
        "selections":[{"slot":request["slots"][0]["slot"],"recipe":request["slots"][0]["choices"][0]["recipe"]}]});
    let admitted=apply(&prepared["state"],admit_body("1"),400,NOW)["state"].clone();
    assert!(admitted["pending_proposal"].is_null());
    assert_eq!(call(json!({"op":"return_proposal","state":admitted,"result":result,"now":NOW}))["ok"],false);
    assert_eq!(validate_cold(admitted.clone(),NOW),admitted);
}

#[test]
fn excluded_then_archived_scope_conflict_preserves_exact_choice_and_blocks_current_food_use() {
    let (state,slot,_)=selected_context();
    let original=saved_selection(&state,&slot).clone();
    let mut week=state["snapshot"]["weeks"][0].clone();week["meal_type_enabled"]["breakfast"]=json!(false);
    // The archived week will have no active selected-history rows. Its own
    // journal presence must still protect the excluded retained source choice.
    week["plan"]["selections"].as_array_mut().unwrap().retain(|selection|selection["recipe"]==packet()["recipe"]);
    week["plan"]["batch_links"].as_array_mut().unwrap().clear();
    let excluded=edit(&state,&week,500,NOW);
    assert_eq!(*saved_selection(&excluded,&slot),original);
    let mut profile=excluded["snapshot"]["profile"].clone();profile["diners"][0]["age_band"]=json!("teen");
    let changed=apply(&excluded,json!({"kind":"update_profile","data":{"expected_profile_revision":profile["revision"],"profile":profile}}),501,NOW)["state"].clone();
    assert_eq!(*saved_selection(&changed,&slot),original);
    assert!(changed["snapshot"]["conflicts"].as_array().unwrap().iter().any(|conflict|
        conflict["slot_ids"].as_array().unwrap().contains(&slot)&&conflict["recipe_refs"].as_array().unwrap().contains(&packet()["recipe"])));
    assert!(porridge_choice(&board(&changed,&slot,NOW)).is_none());
    let archived=apply(&changed,json!({"kind":"open_planning_horizon","data":{}}),502,LATER)["state"].clone();
    assert!(!archived["snapshot"]["weeks"].as_array().unwrap().iter().any(|w|w["range"]["week_id"]==slot["week_id"]));
    assert_eq!(*saved_selection(&archived,&slot),original);
    assert_eq!(validate_cold(archived.clone(),LATER),archived);
    assert!(archived["snapshot"]["conflicts"].as_array().unwrap().iter().any(|conflict|
        conflict["slot_ids"].as_array().unwrap().contains(&slot)&&conflict["recipe_refs"].as_array().unwrap().contains(&packet()["recipe"])));
    let mut erased=archived;
    erased["retained_weeks"].as_array_mut().unwrap().retain(|week|week["range"]["week_id"]!=slot["week_id"]);
    // Synchronise the displayed conflict projection as well: the membership
    // invariant must catch the loss, not merely a now-stale conflict projection.
    erased["snapshot"]["conflicts"].as_array_mut().unwrap().retain(|conflict|
        !conflict["slot_ids"].as_array().unwrap().contains(&slot));
    let last=erased["receipts"].as_array().unwrap().len()-1;
    erased["receipts"][last]["response"]["conflicts"]=erased["snapshot"]["conflicts"].clone();
    rehash_receipt(&mut erased["receipts"][last]);
    assert_eq!(call(json!({"op":"validate_state","state":erased,"now":LATER}))["ok"],false);
    let cold=std::thread::spawn(move||call(json!({"op":"validate_state","state":erased,"now":LATER}))).join().unwrap();
    assert_eq!(cold["ok"],false);
}
